breach.segment:
// MySQL replicas with at least 3 observed minutes. Negative lag (replication inactive) never matches
// here; the "Replication broken" rule covers it.
WHERE marker > 0 AND observed_minutes >= 3
// Threshold: every observed minute at or above 300 s (5 minutes) behind the primary
| WHERE lowest_lag_s >= 300
// Apply (SQL thread) lag is roughly total lag minus network lag
| EVAL apply_lag_s = ROUND(replica_lag_s - COALESCE(network_lag_s, 0), 0),
       replica_lag_s = ROUND(replica_lag_s, 0)
| SORT replica_lag_s DESC, database_id ASC
// Up to 1000 breaching instances per run (the ES|QL default row limit); raise it for larger fleets
| LIMIT 1000
| KEEP database_id, replica_lag_s, network_lag_s, apply_lag_s, observed_minutes
